import json

with open("/app/puzzles.json") as f:
    puzzles = json.load(f)

# Let us test variations of each operator that match ALL 14 queries!
# Queries:
# 1: 13 ⊕ 6 = 20, 4 ⊕ 13 ⊕ 100 = 119
# 2: 13 ⊗ 6 = 77, (300 ⊠ 503) ⊗ (61 ⊞ 90) = 121856, (211 ◇ 827) ⊗ (4 ⊛ 13) = 143070
# 3: 13 ◇ 6 = 13, 211 ◇ 827 = 827
# 4: 13 ▽ 6 = 7, (4 ▽ 13) △ 107 = 0
# 5: 13 ⊘ 6 = 20, 4 ⊘ 13 = -5
# 6: 13 ⊛ 6 = 49, 4 ⊛ 13 = 173
# 7: 13 ⊞ 6 = 19, 61 ⊞ 90 = 151
# 8: 13 ⊠ 6 = 21, 300 ⊠ 503 = 807 (at n=4, i=1, d=1)
# 9: 13 △ 6 = 7, (4 ▽ 13) △ 107 = 0

# Let us test different candidates for ⊘, ⊗, ▽, △, ⊠:
cands_otimes = {
    "a*b-1": lambda a,b,n,i,d: a*b - 1,
    "a*b-1+d": lambda a,b,n,i,d: a*b - 1 + d,
    "a*b-1-d": lambda a,b,n,i,d: a*b - 1 - d,
    "a*b-1+2*d": lambda a,b,n,i,d: a*b - 1 + 2*d,
    "a*b-1-2*d": lambda a,b,n,i,d: a*b - 1 - 2*d,
}

cands_oslash = {
    "2*a-b": lambda a,b,n,i,d: 2*a - b,
    "n*a-b": lambda a,b,n,i,d: n*a - b,
    "(i+1)*a-b": lambda a,b,n,i,d: (i+1)*a - b,
    "(d+2)*a-b": lambda a,b,n,i,d: (d+2)*a - b,
    "2*a-b+d": lambda a,b,n,i,d: 2*a - b + d,
    "2*a-b-d": lambda a,b,n,i,d: 2*a - b - d,
    "2*a-b+i-1": lambda a,b,n,i,d: 2*a - b + i - 1,
    "2*a-b+n-2": lambda a,b,n,i,d: 2*a - b + n - 2,
    "2*a-b-(n-2)": lambda a,b,n,i,d: 2*a - b - (n - 2),
}

cands_nabla = {
    "a-b": lambda a,b,n,i,d: a - b,
    "abs(a-b)": lambda a,b,n,i,d: abs(a - b),
    "a-b+d": lambda a,b,n,i,d: a - b + d,
    "a-b-d": lambda a,b,n,i,d: a - b - d,
    "abs(a-b)+d": lambda a,b,n,i,d: abs(a - b) + d,
    "abs(a-b)-d": lambda a,b,n,i,d: abs(a - b) - d,
    "a-b+i-1": lambda a,b,n,i,d: a - b + i - 1,
    "a-b+n-2": lambda a,b,n,i,d: a - b + n - 2,
    "b+1": lambda a,b,n,i,d: b + 1,
    "(a+1)//2": lambda a,b,n,i,d: (a + 1) // 2,
    "a%b+b": lambda a,b,n,i,d: a % b + b,
    "max(0,a-b)": lambda a,b,n,i,d: max(0, a - b),
    "b-a+14?": lambda a,b,n,i,d: a - b,
}

cands_triangle = {
    "max(0,a-b)": lambda a,b,n,i,d: max(0, a - b),
    "max(0,a-b)+d": lambda a,b,n,i,d: max(0, a - b) + d,
    "max(0,a-b)+i-1?no": lambda a,b,n,i,d: max(0, a - b + d),
}

cands_boxtimes = {
    "a+b+n": lambda a,b,n,i,d: a + b + n,
    "a+b+2*d+2": lambda a,b,n,i,d: a + b + 2*d + 2,
}

base_ops = {
    "⊕": lambda a, b, n, i, d: a + b + 1,
    "◇": lambda a, b, n, i, d: max(a, b),
    "⊛": lambda a, b, n, i, d: a + b ** 2,
    "⊞": lambda a, b, n, i, d: a + b,
}

# Check single-op changes first to see which targets in P2, P4, P5, P7 become reachable!
def check_ops(ops):
    sym = list(ops.keys())
    solved = {}
    for pid, p in puzzles.items():
        a, b, c, d_val = p["numbers"]
        tgt = p["target"]
        hits = []
        for o1 in sym:
            for o2 in sym:
                for o3 in sym:
                    v1 = ops[o3](ops[o2](ops[o1](a, b, 4, 1, 2), c, 4, 2, 1), d_val, 4, 3, 0)
                    if v1 == tgt: hits.append((1, o1, o2, o3))
                    v2 = ops[o3](ops[o1](a, ops[o2](b, c, 4, 2, 2), 4, 1, 1), d_val, 4, 3, 0)
                    if v2 == tgt: hits.append((2, o1, o2, o3))
                    v3 = ops[o2](ops[o1](a, b, 4, 1, 1), ops[o3](c, d_val, 4, 3, 1), 4, 2, 0)
                    if v3 == tgt: hits.append((3, o1, o2, o3))
                    v4 = ops[o1](a, ops[o3](ops[o2](b, c, 4, 2, 2), d_val, 4, 3, 1), 4, 1, 0)
                    if v4 == tgt: hits.append((4, o1, o2, o3))
                    v5 = ops[o1](a, ops[o2](b, ops[o3](c, d_val, 4, 3, 2), 4, 2, 1), 4, 1, 0)
                    if v5 == tgt: hits.append((5, o1, o2, o3))
        if hits:
            solved[pid] = hits
    return solved

# Test changing ONE of {otimes, oslash, nabla, boxtimes} at a time
for name, fn in cands_oslash.items():
    ops = {**base_ops, "⊗": cands_otimes["a*b-1"], "⊘": fn, "▽": cands_nabla["a-b"], "△": cands_triangle["max(0,a-b)"], "⊠": cands_boxtimes["a+b+n"]}
    s = check_ops(ops)
    print(f"oslash={name}: solved {list(s.keys())}")

for name, fn in cands_otimes.items():
    ops = {**base_ops, "⊗": fn, "⊘": cands_oslash["2*a-b"], "▽": cands_nabla["a-b"], "△": cands_triangle["max(0,a-b)"], "⊠": cands_boxtimes["a+b+n"]}
    s = check_ops(ops)
    print(f"otimes={name}: solved {list(s.keys())}")

for name, fn in cands_nabla.items():
    ops = {**base_ops, "⊗": cands_otimes["a*b-1"], "⊘": cands_oslash["2*a-b"], "▽": fn, "△": cands_triangle["max(0,a-b)"], "⊠": cands_boxtimes["a+b+n"]}
    s = check_ops(ops)
    print(f"nabla={name}: solved {list(s.keys())}")

for name, fn in cands_boxtimes.items():
    ops = {**base_ops, "⊗": cands_otimes["a*b-1"], "⊘": cands_oslash["2*a-b"], "▽": cands_nabla["a-b"], "△": cands_triangle["max(0,a-b)"], "⊠": fn}
    s = check_ops(ops)
    print(f"boxtimes={name}: solved {list(s.keys())}")
'
